set -eu
python3 - <<'PY'
import os,stat,json,subprocess,urllib.request,urllib.error,socket,sys
name='gace-createvdobot-videobot-poll-1'
p=subprocess.run(['docker','inspect',name],capture_output=True,text=True,check=True)
info=json.loads(p.stdout)[0]
if info.get('State',{}).get('Running') is not True:raise SystemExit('CREATOR_POLL_NOT_RUNNING')
paths=[m.get('Source') for m in info.get('Mounts',[]) if m.get('Destination')=='/run/secrets/videobot_telegram_token' and m.get('RW') is False]
if len(paths)!=1:raise SystemExit('EXISTING_TOKEN_MOUNT_NOT_UNIQUE')
path=paths[0]
st=os.stat(path)
if not stat.S_ISREG(st.st_mode) or st.st_mode & 0o077:raise SystemExit('TOKEN_FILE_MODE_NOT_PRIVATE')
with open(path,'r',encoding='utf-8') as f: token=f.read().strip()
if not token.split(':',1)[0].isdigit() or ':' not in token:raise SystemExit('TOKEN_FORMAT_INVALID')
_original=socket.getaddrinfo
def ipv4(host,port,family=0,type=0,proto=0,flags=0):
 return _original(host,port,socket.AF_INET,type,proto,flags)
socket.getaddrinfo=ipv4
def call(method,payload):
 url='https://api.telegram.org/bot'+token+'/'+method
 data=json.dumps(payload,ensure_ascii=False).encode('utf-8')
 req=urllib.request.Request(url,data=data,headers={'Content-Type':'application/json'},method='POST')
 try:
  with urllib.request.urlopen(req,timeout=20) as response:
   body=response.read(32768)
 except urllib.error.HTTPError as error:
  try: body=error.read(32768);reply=json.loads(body)
  except Exception:reply={}
  reason=str(reply.get('description','')).lower()
  allowed=['message is not modified','message to edit not found','message can\'t be edited','chat not found','not enough rights','button_url_invalid','button url invalid']
  kind=next((x for x in allowed if x in reason),'OTHER')
  print('TELEGRAM_HTTP='+str(error.code))
  print('TELEGRAM_REJECTION='+kind.replace(' ','_').upper())
  raise SystemExit(73)
 except Exception as error:
  print('TELEGRAM_TRANSPORT_FAILURE='+type(error).__name__)
  raise SystemExit(74)
 try:return json.loads(body)
 except Exception:raise SystemExit('INVALID_TELEGRAM_RESPONSE')
identity=call('getMe',{})
if identity.get('ok') is not True or str(identity.get('result',{}).get('username','')).lower()!='createvdobot':
 raise SystemExit('CREATOR_BOT_IDENTITY_MISMATCH')
reply=call('editMessageReplyMarkup',{'chat_id':-1002373696859,'message_id':4689,'reply_markup':{'inline_keyboard':[[{'text':'⭐ Stars本編・購入はこちら','url':'https://t.me/c/2373696859/4691'}]]}})
if reply.get('ok') is not True or reply.get('result') is not True and reply.get('result',{}).get('message_id')!=4689:
 raise SystemExit('EDIT_ACK_INVALID')
print('PREVIEW_TO_STARLOCK_LINK=PASS')
print('SOURCE_MESSAGE=4689 TARGET_MESSAGE=4691')
PY
